def logical_id(r):
    if r['printed_id'] == 6 and r['name'].startswith('1,1,1,2-'):
        return 7
    if r['printed_id'] == 108 and r['name'] == '1-octanol':
        return 198
    return int(r['printed_id'])

def method_of(r):
    return 'INVSOL' if str(r['method']).startswith('INVSOL') else str(r['method'])

def quality(r, lid, method):
    notes = []
    status = 'OK'
    use = '是'
    grade = 'A_直接实验γ∞'
